"""Measured C4 tables and interactive tiles; saved data only, no inference."""
import argparse,json,html
from pathlib import Path

def run(root,out):
    out.mkdir(parents=True,exist_ok=True);s=json.loads((root/'summary.json').read_text());m=json.loads((root/'manifest.json').read_text());obs=json.loads((root/'observations.json').read_text());lookup={r['id']:r for r in obs}
    for d in s['details']:d.update(claim=lookup[d['id']]['claim'],report=lookup[d['id']]['report'],labels=lookup[d['id']]['labels'])
    families=s['families'];table=''.join('<tr><td>'+html.escape(f)+'</td>'+''.join('<td>'+str(v)+'</td>' for v in (x['assigned'],x['completed'],x['referrals'],x['accepted_wrong'],*[round(100*x['error'][a],2) for a in ('qwen','jev','cascade','matched')]))+'</tr>' for f,x in families.items())
    data=json.dumps(s).replace('<','\\u003c');title=html.escape(m['attempt'])
    audit=json.loads((root/'audit.json').read_text()) if (root/'audit.json').exists() else {}
    cost_note='Actual recorded collection: '+str(audit.get('completed_calls','unknown'))+' completed calls; API USD '+str(audit.get('cost_usd','unknown'))+'. Local Qwen compute is measured in seconds/tokens, not priced dollars.'
    page='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Healing selective helping</title><style>body{font:16px system-ui;background:#eef2f4;color:#152b3b;margin:24px}main{max-width:1250px;margin:auto}p{line-height:1.5}table{border-collapse:collapse;width:100%}td,th{padding:9px;border-bottom:1px solid #ccc;text-align:left}button,select{font:inherit;padding:8px;margin:5px}.tiles{display:flex;flex-wrap:wrap;gap:3px}.tile{width:20px;height:20px;padding:0;border:0;margin:0;border-radius:3px}.card{background:white;padding:20px;border-radius:12px;margin:18px 0}pre{white-space:pre-wrap}.scroll{overflow:auto}</style><main><h1>Healing Helping Hands — TITLE</h1><p>Can Qwen disagreement identify reports that need Jev? Every tile is a recorded report decision, grouped by a stable logical curator ID. This is routing evidence, not a simulation of autonomous cooperation.</p><p>Actual collection calls all controls. Saved Jev consultations below are a counterfactual deployment estimate; both Qwen passes still incur computation. Authored synthetic families do not establish real-world safety or powered non-inferiority.</p><div class="card" id="headline"></div><div class="card"><label>Decision arm <select id="arm"><option value="cascade">Agreement cascade</option><option value="jev">Always Jev</option><option value="qwen">Qwen A</option><option value="matched">Same-count random referral</option></select></label><label>Family <select id="family"><option value="all">All</option></select></label><button id="play">Replay recorded order</button><p>Green correct · red wrong · gray incomplete. Black border means referred. Select a report for its exact saved inputs and answers.</p><div class="tiles" id="tiles"></div><pre id="inspect">Select a report.</pre></div><div class="card scroll"><h2>All family outcomes</h2><table><tr><th>Family</th><th>Assigned</th><th>Complete</th><th>Referred</th><th>Accepted wrong</th><th>Qwen error %</th><th>Jev error %</th><th>Cascade error %</th><th>Matched error %</th></tr>TABLE</table></div></main><script>const DATA=DATAJSON;const $=id=>document.getElementById(id);for(const f of Object.keys(DATA.families))$('family').add(new Option(f,f));$('headline').textContent=`${DATA.completed}/${DATA.assigned} complete; ${DATA.counterfactual_cascade_jev_calls} derived Jev referrals. Avoided ${(100*DATA.jev_calls_avoided_fraction).toFixed(1)}% of Jev consultations. Cascade-minus-Jev error ${(100*DATA.macro_safety_delta).toFixed(2)} points; cascade-minus-matched ${(100*DATA.macro_matched_delta).toFixed(2)} points. Missing decisions: ${DATA.missing}.`;let timer=null,limit=Infinity;function draw(){let rows=DATA.details.filter(r=>$('family').value==='all'||r.family===$('family').value);$('tiles').replaceChildren();rows.slice(0,limit).forEach(r=>{let b=document.createElement('button');b.className='tile';b.title=r.id;b.setAttribute('aria-label',r.id);let arm=$('arm').value;b.style.background=!r.complete?'#a8b0ba':r.correct[arm]?'#19856f':'#c74650';if((arm==='cascade'&&r.referred)||(arm==='matched'&&r.matched_referred)||arm==='jev')b.style.border='2px solid #111';b.onclick=()=>$('inspect').textContent=JSON.stringify(r,null,2);$('tiles').append(b)})}for(let k of ['arm','family'])$(k).onchange=()=>{clearInterval(timer);limit=Infinity;draw()};$('play').onclick=()=>{clearInterval(timer);limit=0;timer=setInterval(()=>{limit+=4;draw();if(limit>=DATA.assigned)clearInterval(timer)},100)};draw();</script>'''.replace('TITLE',title+'<p>'+html.escape(cost_note)+'</p>').replace('TABLE',table).replace('DATAJSON',data)
    (out/'replay.html').write_text(page)
    import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
    fig,axs=plt.subplots(1,2,figsize=(16,7),dpi=120);names=['Qwen A','Always Jev','Agreement cascade','Matched referral'];arms=['qwen','jev','cascade','matched'];err=[sum(v['error'][a] for v in families.values())/len(families) for a in arms];consult=[0,1,1-s['jev_calls_avoided_fraction'],1-s['jev_calls_avoided_fraction']]
    axs[0].bar(names,[v*100 for v in err],color=['#a87832','#245c9c','#19856f','#916eab']);axs[0].set_ylabel('Assigned error %, equal-family mean');axs[0].set_ylim(0,100);axs[0].tick_params(axis='x',rotation=15)
    for n,x,y in zip(names,consult,err):axs[1].scatter(x*100,y*100,s=90,label=n,alpha=.7)
    axs[1].legend(loc='upper right');axs[1].set(xlabel='Derived Jev consultations per 100 reports',ylabel='Assigned error %',xlim=(-5,115),ylim=(-5,105));fig.suptitle('Healing Helping Hands '+m['attempt']+' | measured routing tradeoff');fig.text(.06,.02,'Actual collection calls Jev for every report; plotted consultations are counterfactual. Two Qwen passes are extra compute.\nSynthetic authored families; no powered safety or real-world generalization claim. Missing records remain in assigned denominators.',fontsize=10);fig.tight_layout(rect=[0,.09,1,.94]);fig.savefig(out/'outcomes.png');plt.close(fig)
    print(json.dumps({'rendered':True,'assigned':s['assigned'],'completed':s['completed']}))
if __name__=='__main__':p=argparse.ArgumentParser();p.add_argument('root',type=Path);p.add_argument('out',type=Path);a=p.parse_args();run(a.root,a.out)
